class MyLinkedList {
  struct Node { int val; Node* next; Node(int v):val(v),next(nullptr){} };
  Node* head_ = nullptr; int sz_ = 0;
public:
  int get(int i){ if(i<0||i>=sz_) return -1; Node* p=head_; while(i--) p=p->next; return p->val; }
  void addAtHead(int v){ Node* n=new Node(v); n->next=head_; head_=n; ++sz_; }
  void addAtTail(int v){ if(!head_){addAtHead(v);return;} Node* p=head_; while(p->next)p=p->next; p->next=new Node(v); ++sz_; }
